    checked = value if isinstance(value, (KnownOneof, UnknownOneof)) and ((isinstance(value, KnownOneof) and value.tag == "known") or (isinstance(value, UnknownOneof) and value.tag == "unknown")) else (_ for _ in ()).throw(TypeError("oneof_arm must be a known or unknown discriminated oneof"))
    return checked




