@dataclass(frozen=True)
class Credentials:
    """Credentials accepted by the generated remote facade.

    A zero-value credential uses the platform trust store. Supplying a client
    certificate enables mTLS; bearer credentials are attached by gRPC call
    credentials and never need to be copied into individual RPC calls.
    """

    bearer_token: str | None = None
    root_certificates: bytes | None = None
    certificate_chain: bytes | None = None
    private_key: bytes | None = None

    @classmethod
    def bearer(cls, token: str) -> "Credentials":
        return cls(bearer_token=token)

    @classmethod
    def mtls(
        cls,
        certificate_chain: bytes,
        private_key: bytes,
        root_certificates: bytes | None = None,
        bearer_token: str | None = None,
    ) -> "Credentials":
        return cls(
            bearer_token=bearer_token,
            root_certificates=root_certificates,
            certificate_chain=certificate_chain,
            private_key=private_key,
        )


